'use strict';
/**
 * F30 Cluster: the 6WB-style instrument cluster themes (the 1920x720 "panel" target) drawn through cluster-render.
 *
 * The centre screen is BMW's own (native RHMI) menu, generated by the kit from app.json "screens" (MAIN): the theme
 * showing with its picture, "Change with the drive mode", the theme drop-downs, the status, then every setting
 * (shared/menu.js). "Theme gallery" opens a drawn screen with every theme's picture (shared/gallery.js). The shared
 * engine (hud.js) listens to the settings and redraws at once. It keeps running after the screen is closed (OAP apps
 * stay up in the background), so the screen is only needed for changes.
 */
const mgu = require('./kit/mgu');
const HudApp = require('./hud');
const Menu = require('./menu');
const Gallery = require('./gallery');

const TAGS = {
    wb_comfort: 'white dials', wb_dials: 'white dials, G20 round them', g20_comfort: 'stock G20 look',
    wb_sport: 'red glow', wb_sport_dials: 'red glow, G20 round them', wb_eco: 'blue glow', f30: 'basic',
};

mgu.run({
    start(ctx) {
        let hud;
        try {
            hud = new HudApp(ctx);
        } catch (e) {
            // nothing drawn, but stay up: an exit here would count as a crash on the car
            ctx.log.error('Cluster failed to start: ' + (e && e.stack || e));
            return;
        }
        hud.start();
        // the centre screen: a failure here leaves the cluster drawing (and the kit's own settings rows working)
        try { new Menu(ctx, hud, { tags: TAGS }).start(); } catch (e) { ctx.log.error('menu failed to start: ' + (e && e.stack || e)); }
        try { new Gallery(ctx, hud, { tags: TAGS }).start(); } catch (e) { ctx.log.error('gallery failed to start: ' + (e && e.stack || e)); }
        process.on('exit', () => { try { hud.stop(); } catch (e) { /* exiting anyway */ } });
    },
});
